package piglatin

import (
	"strings"
)

// Sentence translates a sentence from English to Pig Latin, word by word.
func Sentence(sentence string) string {
	words := strings.Fields(sentence)
	for i, word := range words {
		words[i] = transform(word)
	}
	return strings.Join(words, " ")
}

func isVowel(c byte) bool {
	switch c {
	case 'a', 'e', 'i', 'o', 'u':
		return true
	}
	return false
}

// transform applies the Pig Latin rules to a single word.
func transform(word string) string {
	if word == "" {
		return word
	}
	// Rule 1: a word beginning with a vowel, "xr", or "yt" just gets "ay" appended.
	if isVowel(word[0]) || (len(word) > 1 && (word[0:2] == "xr" || word[0:2] == "yt")) {
		return word + "ay"
	}
	// Find where the leading consonant cluster ends.
	i := 0
	for i < len(word) {
		c := word[i]
		if c == 'q' && i+1 < len(word) && word[i+1] == 'u' {
			// Rule 3: "qu" counts as part of the consonant cluster.
			i += 2
			continue
		}
		if isVowel(c) {
			break
		}
		if c == 'y' && i > 0 {
			// Rule 4: a "y" following consonants is treated as a vowel.
			break
		}
		i++
	}
	// Rule 2: move the consonant cluster to the end and append "ay".
	return word[i:] + word[:i] + "ay"
}

